/**
 * The Widow's Oil
 * ---------------
 * A widow of the sons of the prophets pours her little oil into borrowed jars until the oil fills every vessel and saves her sons from slavery. Stage: a poor cottage interior, jars lined up row on row, the oil streaming from one small flask; warm interior light, the widow's astonished hands.
 *
 * Palette 0x2a1a10 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./elisha-kit.js.
 */

import { THREE, createScene, boat, jar, pillar, person } from './elisha-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2321457046, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* boat: hull, sail and oars */
    boat(W, group, 1.4, 0, -2.6, 1.05, { ry: 0.03 });

    jar(W, group, 0.6, 0, -3.8, );

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x372215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2a1a10, ry: 0.03, s: 1.07 });

    return W.finish();
}

export default { build };
